INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pollution Game', 'Pollution Game is a simulation game in the vein of Hamurabi. The player has been elected premier of the Setats Detinu, a small communist island. It''s up to the player to make decisions on the country''s budget so that it can be distributed to countrymen and the treasury. The player must try to keep the country running for eight years without being kicked out of office.' FROM games WHERE igdb_id = 371706 ON CONFLICT (game_id, language_code) DO NOTHING;
