INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trek73', 'Trek73 is a computer game based on the original Star Trek television series. It was created in 1973 by William K. Char, Perry Lee, and Dan Gee. The game simulates battles between space ships of the Star Trek franchise. Through text commands, a player may order the ship to perform certain tasks in battle against an opposing vessel.' FROM games WHERE igdb_id = 16975 ON CONFLICT (game_id, language_code) DO NOTHING;
