INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laser Clay Shooting System', 'The Laser Clay Shooting System is a light gun shooting simulation game created by Nintendo in 1973. The game consisted of an overhead projector which displayed moving targets behind a background; players would fire at the targets with a rifle, in which a mechanism of reflections would determine whether or not the "laser shot" from the rifle hit the target.' FROM games WHERE igdb_id = 39712 ON CONFLICT (game_id, language_code) DO NOTHING;
