INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pong-Tron', 'Sega''s first "video" arcade game. Unlike their earlier amusement games, it uses discrete logic as opposed to being electro-mechanical. The game used boards imported from the United States mounted in a Sega-produced cabinet.' FROM games WHERE igdb_id = 70702 ON CONFLICT (game_id, language_code) DO NOTHING;
