INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lemonade Stand', 'Lemonade Stand is a business simulation game created in 1973 by Bob Jamison of the Minnesota Educational Computing Consortium. Charlie Kellner ported the game to the Apple II platform in February 1979. Throughout the 1980s Apple Computer included Lemonade Stand (along with other software) with the purchase of their systems. The game simulates a child''s lemonade stand, where choices made by the player regarding prices, advertising, etc. will determine the success or failure of the enterprise. The game owed its success to offering just enough variables to make a complex challenge for users, but still providing a simply-grasped addictive introduction to the offsetting priorities facing a business. The choice of the right prices and quantities on the day of a heat-wave could instill the satisfaction unique to a greatly profitable private enterprise. The player is first given a weather report for the day (sunny, cloudy or hot and dry, each accompanied by a color drawing) and is prompted for three values: the number of glasses of lemonade to make, the number of advertising signs, and the cost of lemonade per glass. The program then gives a report of the earnings for that day. A thunderstorm, sometimes occurring on cloudy days and accompanied by a color animation, will void any profits and cause the player to lose any investment for the day. The game can be played either single-player or with up to 30 players (each player is independent and the sales of one do not affect another). The Apple II version included music, with bars from "Morning Mood," "Singin'' in the Rain," "Raindrops Keep Fallin'' on My Head," and "Summertime" played at appropriate moments.' FROM games WHERE igdb_id = 11508 ON CONFLICT (game_id, language_code) DO NOTHING;
