INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asteroid', 'Asteroid was originally developed by Atari for Midway in fulfillment of a contract to supply one video game and one pinball machine. Atari had initially offered Pong during its development to fulfill the contract, but had been rejected. After finishing Asteroid Atari developed a near identical version of the game and released it themselves under the title "Space Race".' FROM games WHERE igdb_id = 170781 ON CONFLICT (game_id, language_code) DO NOTHING;
