INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Davis Cup', 'Taito''s fifth game and the second developed in house. The game is another ball-and-paddle variation, like three of Taito''s previous four releases, but with the added functionality of four players being able to play doubles. This was an important innovation during the 1973-1974 Pong craze first introduced in Allied Leisure''s Tennis Tourney.' FROM games WHERE igdb_id = 172597 ON CONFLICT (game_id, language_code) DO NOTHING;
