INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hockey', 'Hockey was a PONG-clone by RamTeK featuring a somewhat different gameplay by introducing "forward" paddles which were moved simultaneously with the "goalie" paddles. Just like PONG ot got ported to various 1st generation consoles and was also one of the two build-in games for the Fairchild Channel F - the world''s first 2nd generation console.' FROM games WHERE igdb_id = 18585 ON CONFLICT (game_id, language_code) DO NOTHING;
