INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mugwump', 'Mugwump is an early video game where the user is tasked with finding four "Mugwumps" that are randomly hidden on a 10x10 grid. It is a text-based game written in BASIC. The user enters a pair of single-digit co-ordinates in the range from 0 to 9 which are the x,y coordinates to scan. If a mugwump is at that location then the user is alerted. Otherwise the user is told the distance from the scanned coordinates to each of the mugwumps that are yet to be found. The game ends after ten turns or when all of the mugwumps have been found.' FROM games WHERE igdb_id = 11551 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 11551 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
