INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('soccer--4', 172594, '1973-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3w5x.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soccer', 'Soccer is Taito''s third ever video game release and the first developed internally. The game was designed by the highly influential Tomohiro Nishikado, who would later go on to create Space Invaders. Soccer is a ball-and-paddle game like Pong, but with a green background to simulate a playfield, allowing each player to control both a forward and a goalkeeper. The players can adjust the size of the players, who are represented as paddles on screen. It also has a goal on each side. Soccer is likely to be Japan''s first original domestically produced video game, in comparison to Japanese Pong clones released earlier, including Sega''s Pong Tron and Taito''s Elepong. Since it was exported to Europe in 1973 it may also be the first Japanese video game to be released on the European continent.' FROM games WHERE igdb_id = 172594 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 172594 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
