INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gotcha', 'Gotcha is a two-player maze game where the objective is to catch the other player. A maze is displayed on the screen. The first player controls the Pursuer which is represented by a square and the second player controls the Pursued which is represented by a plus sign. As the Pursuer moves closer and closer to the Pursued, an electronic beep sound increases in frequency to a feverish pitch until the Pursuer catches the Pursued. Each time, the Pursuer catches the Pursued, a point is scored and the chase starts over again.' FROM games WHERE igdb_id = 7427 ON CONFLICT (game_id, language_code) DO NOTHING;
